INSERT INTO "drawing_concepts" ("ma", "khai_niem", "qu", "tin_hieu", "mau", "vai_tro", "rong_mm", "cao_mm", "ghi_chu") VALUES ('B07', 'Cột', 'QU-16', 'block', '815', 'IGNORE', NULL, NULL, 'block cột trên layer COLUMN (nha_dan, 55 lần); tên riêng của bản vẽ này');
INSERT INTO "drawing_concepts" ("ma", "khai_niem", "qu", "tin_hieu", "mau", "vai_tro", "rong_mm", "cao_mm", "ghi_chu") VALUES ('B08', 'Cao độ', 'QU-06', 'block', 'COS-MB', 'ANNOTATION', NULL, NULL, 'ký hiệu cao độ mặt bằng (nha_dan)');
INSERT INTO "drawing_concepts" ("ma", "khai_niem", "qu", "tin_hieu", "mau", "vai_tro", "rong_mm", "cao_mm", "ghi_chu") VALUES ('B09', 'Ký hiệu trục', 'QU-07', 'block', 'KHT', 'ANNOTATION', NULL, NULL, 'đầu trục (nha_pho)');
INSERT INTO "drawing_concepts" ("ma", "khai_niem", "qu", "tin_hieu", "mau", "vai_tro", "rong_mm", "cao_mm", "ghi_chu") VALUES ('B10', 'Mũi tên', 'QU-08', 'block', 'MUI-TEN', 'ANNOTATION', NULL, NULL, 'mũi tên chỉ hướng (nha_dan)');
INSERT INTO "drawing_concepts" ("ma", "khai_niem", "qu", "tin_hieu", "mau", "vai_tro", "rong_mm", "cao_mm", "ghi_chu") VALUES ('B11', 'Kích thước', 'QU-08', 'block', '_OBLIQUE', 'ANNOTATION', NULL, NULL, 'nét gạch chéo đầu đường kích thước của AutoCAD');
INSERT INTO "drawing_concepts" ("ma", "khai_niem", "qu", "tin_hieu", "mau", "vai_tro", "rong_mm", "cao_mm", "ghi_chu") VALUES ('B12', 'Nội thất', 'QU-11', 'block', 'SOFA', 'IGNORE', NULL, NULL, 'SOFA, SOFA4150 (nha_dan)');
